pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, address recipient, uint256 v) public {
        // Use an empty recipient array so the length guard (the only difference) is the deciding factor.
        address[] memory tos = new address[](0);

        bool ok;
        try c.transfer(from, recipient, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: empty _tos violates `require(_tos.length > 0)` -> revert -> ok == false.
        // Mutant: `require(_tos.length >= 0)` always holds -> loop body never executes -> returns true -> ok == true.
        assertTrue(ok == false);
    }
}
